import {boundsOf,clamp} from './model.mjs';
export function resizeRect(r,handle,dx,dy,{shift=false,alt=false,min=25}={}){const left=handle.includes('w'),top=handle.includes('n'),horizontal=/[we]/.test(handle),vertical=/[ns]/.test(handle);let w=horizontal?Math.max(min,r.w+(left?-dx:dx)*(alt?2:1)):r.w,h=vertical?Math.max(min,r.h+(top?-dy:dy)*(alt?2:1)):r.h;if(shift){const ratio=r.w/r.h;if(horizontal&&vertical){if(Math.abs(w-r.w)>Math.abs(h-r.h)*ratio)h=Math.max(min,w/ratio);else w=Math.max(min,h*ratio);}else if(horizontal)h=Math.max(min,w/ratio);else w=Math.max(min,h*ratio);}if(shift){const factor=Math.max(w/r.w,h/r.h,min/r.w,min/r.h);w=r.w*factor;h=r.h*factor;}return {x:alt?r.x+(r.w-w)/2:left?r.x+r.w-w:r.x,y:alt?r.y+(r.h-h)/2:top?r.y+r.h-h:r.y,w,h};}
export function scaleBlocks(blocks,from,to){return blocks.map(b=>({...b,x:to.x+(b.x-from.x)*to.w/from.w,y:to.y+(b.y-from.y)*to.h/from.h,w:Math.max(25,b.w*to.w/from.w),h:Math.max(25,b.h*to.h/from.h)}));}
export function rotateBlocks(blocks,delta,box=boundsOf(blocks)){const a=delta*Math.PI/180,cx=box.x+box.w/2,cy=box.y+box.h/2;return blocks.map(b=>{const x=b.x+b.w/2-cx,y=b.y+b.h/2-cy;return {...b,x:cx+x*Math.cos(a)-y*Math.sin(a)-b.w/2,y:cy+x*Math.sin(a)+y*Math.cos(a)-b.h/2,rotation:(Number(b.rotation)||0)+delta};});}
export function smartSnap(box,others,guides=[],sensitivity=6,{grid=false,elements=true,page=true}={}){let dx=0,dy=0,lines=[];for(const axis of ['x','y']){const size=axis==='x'?'w':'h',extent=axis==='x'?1920:1431,anchors=[box[axis],box[axis]+box[size]/2,box[axis]+box[size]],targets=[...(page?[0,extent/2,extent]:[]),...guides.filter(g=>g.axis===axis).map(g=>g.position),...(elements?others.flatMap(b=>[b[axis],b[axis]+b[size]/2,b[axis]+b[size]]):[])];let best=sensitivity+1,delta=0,target;for(const a of anchors)for(const t of targets){if(Math.abs(t-a)<best){best=Math.abs(t-a);delta=t-a;target=t;}}// Equal gaps between adjacent elements.
 if(elements){const ordered=others.filter(b=>axis==='x'?Math.abs(b.y-box.y)<Math.max(b.h,box.h):Math.abs(b.x-box.x)<Math.max(b.w,box.w)).sort((a,b)=>a[axis]-b[axis]);for(let i=1;i<ordered.length;i++){const gap=ordered[i][axis]-ordered[i-1][axis]-ordered[i-1][size];for(const t of [ordered[i][axis]+ordered[i][size]+gap,ordered[i-1][axis]-gap-box[size]])if(Math.abs(t-box[axis])<best){best=Math.abs(t-box[axis]);delta=t-box[axis];target=t;}}}
 if(best<=sensitivity)lines.push({axis,position:target});else if(grid)delta=Math.round(box[axis]/10)*10-box[axis];if(axis==='x')dx=delta;else dy=delta;}return {dx,dy,lines};}
export function installTransforms(E){let operation=null,pan=null,space=false,lines=[];const $=s=>document.querySelector(s),wrap=$('#stageWrap'),viewport=$('#stageViewport');const point=e=>{const r=wrap.getBoundingClientRect();return {x:(e.clientX-r.left)/E.scale,y:(e.clientY-r.top)/E.scale};};
 function start(e,type,handle){if(E.mode!=='edit'||!E.movable().length)return;const blocks=E.movable().map(b=>structuredClone(b)),box=boundsOf(blocks),p=point(e);operation={type,handle,start:p,blocks,box,before:E.snapshot(),angle:Math.atan2(p.y-box.y-box.h/2,p.x-box.x-box.w/2),moved:false};e.preventDefault();}
 function render(){const root=$('#guideOverlay');if(!root)return;root.hidden=E.mode!=='edit';let html='';const doc=E.doc;if(doc.showGuides!==false){for(const g of doc.guides||[])html+=`<div class="manual-guide ${g.axis}" data-guide="${g.id}" style="${g.axis==='x'?'left':'top'}:${g.position*E.scale}px" title="Guia ${Math.round(g.position)} · dois cliques para excluir"></div>`;}for(const g of lines)html+=`<div class="smart-guide ${g.axis}" style="${g.axis==='x'?'left':'top'}:${g.position*E.scale}px"></div>`;root.innerHTML=html;
 const blocks=E.selectedBlocks();if(blocks.length){const b=boundsOf(blocks),outside=blocks.some(b=>b.x<0||b.y<0||b.x+b.w>1920||b.y+b.h>1431);$('#transformStatus').textContent=`X ${Math.round(b.x)} · Y ${Math.round(b.y)} · ${Math.round(b.w)} × ${Math.round(b.h)}${outside?' · Área externa não será exportada':''}`;}else $('#transformStatus').textContent='1920 × 1431';
 const ruler=(axis,len)=>Array.from({length:Math.floor(len/100)+1},(_,i)=>`<span style="${axis==='x'?'left':'top'}:${i*100*E.scale}px">${i*100}</span>`).join('');$('#rulerX').innerHTML=ruler('x',1920);$('#rulerY').innerHTML=ruler('y',1431);}
 $('#selectionOverlay').addEventListener('pointerdown',e=>{const h=e.target.dataset.resize;if(h){e.stopPropagation();start(e,h==='rotate'?'rotate':'resize',h);}});
 viewport.addEventListener('pointerdown',e=>{if(space||e.button===1){e.preventDefault();e.stopPropagation();pan={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};}},true);
 window.addEventListener('pointermove',e=>{if(pan){viewport.scrollLeft=pan.left-e.clientX+pan.x;viewport.scrollTop=pan.top-e.clientY+pan.y;return;}if(!operation)return;const p=point(e),o=operation;let dx=p.x-o.start.x,dy=p.y-o.start.y;if(Math.abs(dx)+Math.abs(dy)<1)return;o.moved=true;if(o.type==='guide'){const g=E.doc.guides.find(g=>g.id===o.id);g.position=clamp(p[g.axis],0,g.axis==='x'?1920:1431);render();return;}let result;
 if(o.type==='move'){let box={...o.box,x:o.box.x+dx,y:o.box.y+dy};if($('#snapToggle').checked&&!e.altKey){const settings=E.doc.snap||{},snapped=smartSnap(box,E.doc.blocks.filter(b=>!o.blocks.some(x=>x.id===b.id)&&b.visible),E.doc.guides||[],settings.sensitivity||6,{grid:settings.grid??true,elements:settings.elements??true,page:settings.guides??true});dx+=snapped.dx;dy+=snapped.dy;lines=snapped.lines;}else lines=[];result=o.blocks.map(b=>({...b,x:b.x+dx,y:b.y+dy}));}
 else if(o.type==='rotate'){let angle=(Math.atan2(p.y-o.box.y-o.box.h/2,p.x-o.box.x-o.box.w/2)-o.angle)*180/Math.PI;if(e.shiftKey)angle=Math.round(angle/15)*15;result=rotateBlocks(o.blocks,angle,o.box);}
 else{if(o.blocks.length===1&&o.blocks[0].rotation){const a=o.blocks[0].rotation*Math.PI/180,lx=dx*Math.cos(a)+dy*Math.sin(a),ly=-dx*Math.sin(a)+dy*Math.cos(a),to=resizeRect(o.box,o.handle,lx,ly,{shift:e.shiftKey||o.blocks[0].lockRatio,alt:e.altKey}),cx=o.box.x+o.box.w/2,cy=o.box.y+o.box.h/2,ox=to.x+to.w/2-cx,oy=to.y+to.h/2-cy;to.x=cx+ox*Math.cos(a)-oy*Math.sin(a)-to.w/2;to.y=cy+ox*Math.sin(a)+oy*Math.cos(a)-to.h/2;result=scaleBlocks(o.blocks,o.box,to);}else result=scaleBlocks(o.blocks,o.box,resizeRect(o.box,o.handle,dx,dy,{shift:e.shiftKey||o.blocks.every(b=>b.lockRatio),alt:e.altKey}));}
 for(const b of result)Object.assign(E.doc.blocks.find(x=>x.id===b.id),b);if(o.type==='move'||o.type==='rotate')E.updateTransforms();else E.draw();render();});
 const finish=()=>{pan=null;if(!operation)return;const o=operation;operation=null;lines=[];if(o.moved){E.record(o.before);E.save();E.draw();E.inspector();}render();};window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',()=>cancel());
 function cancel(){if(operation){E.replace(operation.before);operation=null;lines=[];E.draw();E.inspector();}pan=null;render();}
 window.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.target.closest('input,textarea,select,[contenteditable]')){space=true;e.preventDefault();viewport.classList.add('panning');}if(e.key==='Escape')cancel();});window.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;viewport.classList.remove('panning');}});window.addEventListener('blur',()=>{space=false;pan=null;finish();});
 viewport.addEventListener('wheel',e=>{if(!(e.ctrlKey||e.metaKey))return;e.preventDefault();const r=wrap.getBoundingClientRect(),old=E.scale,x=(e.clientX-r.left)/old,y=(e.clientY-r.top)/old;E.zoom(clamp(old*Math.exp(-e.deltaY*.002),.1,3));const after=wrap.getBoundingClientRect();viewport.scrollLeft+=after.left+x*E.scale-e.clientX;viewport.scrollTop+=after.top+y*E.scale-e.clientY;},{passive:false});
 for(const [id,axis] of [['rulerX','y'],['rulerY','x']])$('#'+id).addEventListener('pointerdown',e=>{if(E.mode!=='edit'||E.doc.lockGuides)return;if((E.doc.guides||[]).length>=200){E.toast('Limite de 200 guias.');return;}const before=E.snapshot(),g={id:crypto.randomUUID(),axis,position:point(e)[axis]};(E.doc.guides??=[]).push(g);operation={type:'guide',id:g.id,before,start:point(e),moved:true};e.preventDefault();render();});
 $('#guideOverlay').addEventListener('pointerdown',e=>{const id=e.target.dataset.guide;if(!id||E.doc.lockGuides)return;operation={type:'guide',id,before:E.snapshot(),start:point(e),moved:false};e.preventDefault();});$('#guideOverlay').addEventListener('dblclick',e=>{if(e.target.dataset.guide&&!E.doc.lockGuides)E.change(()=>E.doc.guides=E.doc.guides.filter(g=>g.id!==e.target.dataset.guide),true,true);});
 return {start,render,cancel,isPanning:()=>space||!!pan};}
